    } else {
      arr.push(c);
    }
  }
  return arr;
}

function setChildren(parent, arr) {
  let c = parent.firstChild;
  while (c) {
    const nx = c.next;
    c.unlink();
    c = nx;
  }
  for (const n of arr) parent.appendChild(n);
}

