    },

    async renderApi({ readJson }) {
      const b = await readJson();
      if (!b || typeof b.markdown !== 'string') throw bad('markdown must be a string');
      return { status: 200, json: { html: renderBody(b.markdown), toc: toc(b.markdown) } };
    },

