    $('#d-to').value = String(versions[0].version);
  }
}

async function showDiff() {
  const from = $('#d-from').value;
  const to = $('#d-to').value;
  const d = await api(`/api/pages/${enc(current.slug)}/diff?from=${from}&to=${to}`);
