      <tbody>${versions
        .map(
          (v) =>
            `<tr><td>v${v.version}</td><td>${esc(v.title)}</td><td>${esc(when(v.updatedAt))}</td>` +
            `<td><button type="button" data-act="view" data-v="${v.version}">View</button></td></tr>`,
        )
        .join('')}</tbody>
    </table>
    <section class="panel">
      <h3>Diff</h3>
